#!/usr/bin/env bash
# Prepends the vX.Y.Z section, generated by git-cliff from the Conventional Commits since the
# last release tag, to CHANGELOG.md. Commit the result as `chore(release): prepare vX.Y.Z`
# (cliff.toml skips that prefix) and merge it before release-tag.sh, which refuses a version
# CHANGELOG.md does not list. Never commits.
# Usage: release-changelog.sh <git-cliff> <X.Y.Z>
set -euo pipefail
# shellcheck source=scripts/release-common.sh
source "$(dirname "${BASH_SOURCE[0]}")/release-common.sh"

cliff="${1:?usage: release-changelog.sh <git-cliff> <X.Y.Z>}"
check_release_version release:changelog "${2:-}"
! grep -qF "## [$version] - " CHANGELOG.md ||
  die "CHANGELOG.md already has a $version section" "git diff CHANGELOG.md"
release_notes "$cliff" >/dev/null

"$cliff" --config cliff.toml --unreleased --tag "v$version" --prepend CHANGELOG.md >/dev/null
echo "✓ added $version to CHANGELOG.md"
echo "  review and edit: git diff CHANGELOG.md"
echo "  then commit as: chore(release): prepare v$version"
